function validate([s, num1, num2]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 characters.';
  if (!/^[01]+$/.test(s)) return 's may contain only 0 and 1.';
  if (!Number.isInteger(num1) || num1 < 1 || num1 > s.length) return 'num1 is between 1 and the length of s.';
  if (!Number.isInteger(num2) || num2 < 1 || num2 > s.length) return 'num2 is between 1 and the length of s.';
  let a = num1, b = num2;
  while (b) [a, b] = [b, a % b];
  if (a !== 1) return 'num1 and num2 must be coprime.';
  return null;
}

