function fixedRatio(s, num1, num2) {
  const seen = new Map([[0, 1]]);
  let balance = 0;
  let count = 0;
  for (const ch of s) {
    if (ch === '0') {
      balance += num2;
    } else {
      balance -= num1;
    }
    const matches = seen.get(balance) ?? 0;
    count += matches;
    seen.set(balance, matches + 1);
  }
  return count;
}

