function fixedRatio(s, num1, num2) {
  // Try every substring and keep running counts of each character.
  let total = 0;
  for (let start = 0; start < s.length; start++) {
    let zeros = 0, ones = 0;
    for (let end = start; end < s.length; end++) {
      if (s[end] === '0') zeros++; else ones++;
      if (zeros * num2 === ones * num1) total++;
    }
  }
  return total;
}

