function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const length = size === 'large' ? int(8000, 10000) : int(1, 12);
  const cap = size === 'large' ? (rand() < 0.8 ? 6 : 200) : Math.min(length, 4);
  let num1, num2;
  do {
    num1 = int(1, Math.min(cap, length));
    num2 = int(1, Math.min(cap, length));
  } while (gcd(num1, num2) !== 1);
  // Bias the mix of characters toward the target ratio so that matches are common.
  const zeroChance = rand() < 0.8 ? num1 / (num1 + num2) : rand();
  let s = '';
  for (let i = 0; i < length; i++) s += rand() < zeroChance ? '0' : '1';
  return [s, num1, num2];
}
